def reverse_complement(dna_sequence):
    """
    Computes the reverse complement of a DNA sequence.

    Args:
        dna_sequence (str): A string representing the DNA sequence.

    Returns:
        str: The reverse complement of the input DNA sequence.
    """
    # Define the complementary bases
    complement_dict = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
    
    # Ensure the sequence is in uppercase
    sequence_upper = dna_sequence.upper()
    
    # Get the complement sequence
    complement_seq = "".join([complement_dict.get(base, base) for base in sequence_upper])
    
    # Reverse the complement sequence
    reverse_comp_seq = complement_seq[::-1]
    
    return reverse_comp_seq

# --- Example Usage ---
my_sequence = ""
rev_comp = reverse_complement(my_sequence)

print(f"Original Sequence:  5'-{my_sequence}-3'")
print(f"Reverse Complement: 3'-{rev_comp}-5'") 
